import { parseFormula, collectRefs, makeEvaluator, parseAddr, colIndex } from './sheet.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const s = lines[i].replace(/^[ \t]+/, '')
  if (s === '' || s[0] === '#') continue
  const m = /^[^ \t]*/.exec(s)[0]
  const rest = s.slice(m.length).replace(/^[ \t]/, '').replace(/^[ \t]*/, '')
  const a = parseAddr(m)
  if (!a) fail(`error: line ${i + 1}: invalid cell address ${m}`)
  if (cells.has(a.key)) fail(`error: line ${i + 1}: cell ${a.key} is declared twice`)
  cells.set(a.key, { ...a, content: rest })
}

function fail(msg) {
  process.stderr.write(msg + '\n')
  process.exit(2)
}

const list = [...cells.values()].sort((x, y) => colIndex(x.col) - colIndex(y.col) || x.row - y.row)
let out = ''
if (mode === 'values') {
  const ev = makeEvaluator(cells)
  for (const c of list) out += `${c.key}=${ev.format(ev.cell(c.key))}\n`
} else {
  for (const c of list) {
    let names = []
    if (c.content[0] === '=') {
      const ast = parseFormula(c.content.slice(1))
      if (ast) names = collectRefs(ast)
    }
    out += `${c.key}:${names.map((n) => ' ' + n).join('')}\n`
  }
}
process.stdout.write(out)
"}

