{"file_path":"src/sheet.js","content":"export function colIndex(col) {
  if (col.length === 1) return col.charCodeAt(0) - 64
  return 26 + (col.charCodeAt(0) - 65) * 26 + (col.charCodeAt(1) - 64)
}

function colName(idx) {
  if (idx <= 26) return String.fromCharCode(64 + idx)
  const r = idx - 27
  return String.fromCharCode(65 + Math.floor(r / 26)) + String.fromCharCode(65 + (r % 26))
}

export function parseAddr(w) {
  const m = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(w)
  if (!m) return null
  const row = Number(m[2])
  if (row < 1) return null
  const col = m[1].toUpperCase()
  return { col, row, key: col + row }
}

function tokenize(src) {
  const toks = []
  let i = 0
  while (i < src.length) {
    const c = src[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(src.slice(i)))) {
      toks.push({ t: 'num', v: Number(m[0]) }); i += m[0].length
    } else if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(src.slice(i)))) {
      toks.push({ t: 'word', v: m[0] }); i += m[0].length
    } else if ((m = /^(<>|<=|>=|[-+*/^=<>(),:])/.exec(src.slice(i)))) {
      toks.push({ t: 'op', v: m[0] }); i += m[0].length
    } else return null
  }
  return toks
}

// Returns an AST or null when the grammar rejects the formula.
export function parseFormula(src) {
  const toks = tokenize(src)
  if (!toks) return null
  let p = 0
  const bad = new Error('syntax')
  const isOp = (v) => p < toks.length && toks[p].t === 'op' && toks[p].v === v
  const isWordAt = (k) => k < toks.length && toks[k].t === 'word'

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].t === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw bad
    const t = toks[p]
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
    if (t.t === 'op' && t.v === '(') {
      p++
      const e = cmp()
      if (!isOp(')')) throw bad
      p++
      return e
    }
    if (t.t === 'word') {
      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: t.v }
    }
    throw bad
  }
  function arg() {
    if (isWordAt(p) && p + 2 < toks.length + 0 && toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === ':') {
      if (!isWordAt(p + 2)) throw bad
      const a = toks[p].v, b = toks[p + 2].v
      const after = toks[p + 3]
      if (after && after.t === 'op' && after.v === '(') throw bad
      p += 3
      if (!(isOp(',') || isOp(')'))) throw bad
      return { k: 'range', a, b }
    }
    return cmp()
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === bad) return null
    throw e
  }
}

function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const c1 = Math.min(colIndex(x.col), colIndex(y.col)), c2 = Math.max(colIndex(x.col), colIndex(y.col))
  const r1 = Math.min(x.row, y.row), r2 = Math.max(x.row, y.row)
  const keys = []
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) keys.push(colName(c) + r)
  return keys
}

export function collectRefs(ast) {
  const set = new Set()
  const walk = (n) => {
    if (n.k === 'ref') { const a = parseAddr(n.w); if (a) set.add(a.key) }
    else if (n.k === 'range') { const ks = rangeCells(n.a, n.b); if (ks) ks.forEach((k) => set.add(k)) }
    else if (n.k === 'bin') { walk(n.l); walk(n.r) }
    else if (n.k === 'un') walk(n.e)
    else if (n.k === 'call') n.args.forEach(walk)
  }
  walk(ast)
  return [...set].sort((x, y) => {
    const a = parseAddr(x), b = parseAddr(y)
    return colIndex(a.col) - colIndex(b.col) || a.row - b.row
  })
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ e })
const isErr = (v) => typeof v === 'object'
const NUMRE = /^-?[0-9]+(\.[0-9]+)?$/

function rank(v) { return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2 }
function cmpCode(a, b) {
  const x = Array.from(a), y = Array.from(b)
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const d = x[i].codePointAt(0) - y[i].codePointAt(0)
    if (d) return d
  }
  return x.length - y.length
}

export function makeEvaluator(cells) {
  const memo = new Map()
  const busy = new Set()

  function cell(key) {
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return 0
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    let v
    const s = c.content
    if (s[0] === '=') {
      const ast = parseFormula(s.slice(1))
      v = ast ? evalNode(ast) : err('#ERR!')
    } else if (s === '') v = 0
    else if (NUMRE.test(s)) v = Number(s)
    else if (ERRS.includes(s)) v = err(s)
    else v = s
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function ref(w) {
    const a = parseAddr(w)
    return a ? cell(a.key) : err('#REF!')
  }

  function num(v) {
    if (isErr(v)) return v
    if (typeof v === 'boolean') return v ? 1 : 0
    if (typeof v === 'string') return err('#VALUE!')
    return v
  }
  const fin = (x) => (Number.isFinite(x) ? x : err('#DIV/0!'))

  // Values of an argument, ranges expanded.
  function argValues(a) {
    if (a.k === 'range') {
      const ks = rangeCells(a.a, a.b)
      if (!ks) return [err('#REF!')]
      return ks.map(cell)
    }
    return [evalNode(a)]
  }

  function evalNode(n) {
    switch (n.k) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'ref': return ref(n.w)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = num(evalNode(n.e))
        if (isErr(v)) return v
        return n.op === '-' ? -v : v
      }
      case 'bin': {
        const l = evalNode(n.l)
        if (isErr(l)) return l
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const r = evalNode(n.r)
          if (isErr(r)) return r
          const ra = rank(l), rb = rank(r)
          let d
          if (ra !== rb) d = ra - rb
          else if (ra === 0) d = l < r ? -1 : l > r ? 1 : 0
          else if (ra === 1) d = cmpCode(l, r)
          else d = Number(l) - Number(r)
          switch (n.op) {
            case '=': return d === 0
            case '<>': return d !== 0
            case '<': return d < 0
            case '<=': return d <= 0
            case '>': return d > 0
            default: return d >= 0
          }
        }
        const a = num(l)
        if (isErr(a)) return a
        const r = evalNode(n.r)
        const b = num(r)
        if (isErr(b)) return b
        switch (n.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
          default: return fin(Math.pow(a, b))
        }
      }
      case 'call': return call(n)
    }
    return err('#ERR!')
  }

  function call(n) {
    const name = n.name
    const k = n.args.length
    if (name === 'IF') {
      if (k !== 3) return err('#ERR!')
      const one = (a) => {
        const vs = argValues(a)
        return vs.length === 1 ? vs[0] : err('#ERR!')
      }
      const c = one(n.args[0])
      if (isErr(c)) return c
      if (typeof c === 'string') return err('#VALUE!')
      const truth = typeof c === 'boolean' ? c : c !== 0
      return one(n.args[truth ? 1 : 2])
    }
    if (name === 'ABS') {
      if (k !== 1) return err('#ERR!')
      const vs = argValues(n.args[0])
      if (vs.length !== 1) return err('#ERR!')
      const v = num(vs[0])
      return isErr(v) ? v : Math.abs(v)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return err('#NAME?')
    if (k < 1) return err('#ERR!')
    const vals = []
    for (const a of n.args) vals.push(...argValues(a))
    const e = vals.find(isErr)
    if (e) return e
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const nums = []
    for (const v of vals) {
      const x = num(v)
      if (isErr(x)) return x
      nums.push(x)
    }
    if (name === 'MIN') return Math.min(...nums)
    if (name === 'MAX') return Math.max(...nums)
    const sum = nums.reduce((s, x) => s + x, 0)
    return fin(name === 'SUM' ? sum : sum / nums.length)
  }

  function format(v) {
    if (isErr(v)) return v.e
    if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
    if (typeof v === 'string') return v
    return String(Number(v.toPrecision(10)))
  }

  return { cell, format }
}
"}

