      l = { k: 'bin', op, l, r: mul() }
    }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) {
      const op = toks[p++].v
      l = { k: 'bin', op, l, r: pow() }
    }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { k: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) {
      const op = toks[p++].v
      return { k: 'un', op, e: unary() }
    }
    return primary()
  }
  function primary() {
    if (p >= toks.length) throw bad
    const t = toks[p]
    if (t.t === 'num') { p++; return { k: 'num', v: t.v } }
