      p++
      if (isOp('(')) {
        p++
        const args = []
        if (isOp(')')) { p++; return { k: 'call', name: t.v.toUpperCase(), args } }
        for (;;) {
          args.push(arg())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          throw bad
        }
        return { k: 'call', name: t.v.toUpperCase(), args }
      }
      const u = t.v.toUpperCase()
      if (u === 'TRUE') return { k: 'bool', v: true }
      if (u === 'FALSE') return { k: 'bool', v: false }
      return { k: 'ref', w: t.v }
    }
    throw bad
  }
  function arg() {
    if (isWordAt(p) && p + 2 < toks.length + 0 && toks[p + 1] && toks[p + 1].t === 'op' && toks[p + 1].v === ':') {
