      return { k: 'range', a, b }
    }
    return cmp()
  }

  try {
    const e = cmp()
    if (p !== toks.length) return null
    return e
  } catch (e) {
    if (e === bad) return null
    throw e
  }
}

function rangeCells(a, b) {
  const x = parseAddr(a), y = parseAddr(b)
  if (!x || !y) return null
  const c1 = Math.min(colIndex(x.col), colIndex(y.col)), c2 = Math.max(colIndex(x.col), colIndex(y.col))
  const r1 = Math.min(x.row, y.row), r2 = Math.max(x.row, y.row)
  const keys = []
  for (let c = c1; c <= c2; c++) for (let r = r1; r <= r2; r++) keys.push(colName(c) + r)
  return keys
}

export function collectRefs(ast) {
  const set = new Set()
  const walk = (n) => {
    if (n.k === 'ref') { const a = parseAddr(n.w); if (a) set.add(a.key) }
    else if (n.k === 'range') { const ks = rangeCells(n.a, n.b); if (ks) ks.forEach((k) => set.add(k)) }
    else if (n.k === 'bin') { walk(n.l); walk(n.r) }
    else if (n.k === 'un') walk(n.e)
    else if (n.k === 'call') n.args.forEach(walk)
  }
  walk(ast)
  return [...set].sort((x, y) => {
    const a = parseAddr(x), b = parseAddr(y)
    return colIndex(a.col) - colIndex(b.col) || a.row - b.row
  })
}

const ERRS = ['#DIV/0!', '#REF!', '#VALUE!', '#CYCLE!', '#NAME?', '#ERR!']
const err = (e) => ({ e })
const isErr = (v) => typeof v === 'object'
const NUMRE = /^-?[0-9]+(\.[0-9]+)?$/

function rank(v) { return typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2 }
