}

export function makeEvaluator(cells) {
  const memo = new Map()
  const busy = new Set()

  function cell(key) {
    if (memo.has(key)) return memo.get(key)
    const c = cells.get(key)
    if (!c) return 0
    if (busy.has(key)) return err('#CYCLE!')
    busy.add(key)
    let v
    const s = c.content
    if (s[0] === '=') {
      const ast = parseFormula(s.slice(1))
      v = ast ? evalNode(ast) : err('#ERR!')
    } else if (s === '') v = 0
    else if (NUMRE.test(s)) v = Number(s)
    else if (ERRS.includes(s)) v = err(s)
    else v = s
    busy.delete(key)
    memo.set(key, v)
    return v
  }

  function ref(w) {
    const a = parseAddr(w)
    return a ? cell(a.key) : err('#REF!')
  }

  function num(v) {
    if (isErr(v)) return v
    if (typeof v === 'boolean') return v ? 1 : 0
    if (typeof v === 'string') return err('#VALUE!')
    return v
  }
  const fin = (x) => (Number.isFinite(x) ? x : err('#DIV/0!'))

  // Values of an argument, ranges expanded.
  function argValues(a) {
    if (a.k === 'range') {
      const ks = rangeCells(a.a, a.b)
      if (!ks) return [err('#REF!')]
      return ks.map(cell)
    }
    return [evalNode(a)]
  }

  function evalNode(n) {
    switch (n.k) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'ref': return ref(n.w)
      case 'range': return err('#ERR!')
      case 'un': {
        const v = num(evalNode(n.e))
        if (isErr(v)) return v
        return n.op === '-' ? -v : v
      }
      case 'bin': {
        const l = evalNode(n.l)
        if (isErr(l)) return l
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const r = evalNode(n.r)
          if (isErr(r)) return r
          const ra = rank(l), rb = rank(r)
          let d
          if (ra !== rb) d = ra - rb
          else if (ra === 0) d = l < r ? -1 : l > r ? 1 : 0
          else if (ra === 1) d = cmpCode(l, r)
          else d = Number(l) - Number(r)
          switch (n.op) {
            case '=': return d === 0
            case '<>': return d !== 0
            case '<': return d < 0
            case '<=': return d <= 0
            case '>': return d > 0
            default: return d >= 0
          }
        }
        const a = num(l)
        if (isErr(a)) return a
        const r = evalNode(n.r)
        const b = num(r)
        if (isErr(b)) return b
        switch (n.op) {
          case '+': return fin(a + b)
          case '-': return fin(a - b)
          case '*': return fin(a * b)
          case '/': return b === 0 ? err('#DIV/0!') : fin(a / b)
          default: return fin(Math.pow(a, b))
